mapper.update:
UPDATE backup_policy
SET enabled            = #{policy.enabled},
    archive_after_days = #{policy.archiveAfterDays},
    keep_days          = #{policy.keepDays},
    updated_at         = #{policy.updatedAt}
WHERE store_id = #{policy.storeId}

mapper.select:
SELECT  FROM backup_archive

    store_id = #{storeId}
    AND status = #{status}

ORDER BY log_day DESC, store_id
LIMIT #{limit}
